{"jobs": [{"absolute_url": "https://job-boards.greenhouse.io/affirm/jobs/7712707003", "data_compliance": [{"type": "gdpr", "requires_consent": false, "requires_processing_consent": false, "requires_retention_consent": false, "retention_period": null, "demographic_data_consent_applies": false}], "internal_job_id": 5755370003, "location": {"name": "Remote US"}, "metadata": [{"id": 4128552003, "name": "External Department", "value": "Revenue", "value_type": "single_select"}, {"id": 28890347003, "name": "PERM Job?", "value": false, "value_type": "yes_no"}], "id": 7712707003, "updated_at": "2026-08-19T17:03:11-04:00", "requisition_id": "JR103918", "title": "Business Development Associate", "company_name": "Affirm", "first_published": "2026-05-18T10:22:09-04:00", "language": "en", "application_deadline": null, "content": "&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Affirm is reinventing credit to make it more honest and friendly, giving consumers the flexibility to buy now and pay later without any hidden fees or compounding interest.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;
&lt;p&gt;The Business Development team works in lockstep with our Key and Enterprise Sales team to identify top-of-funnel opportunities within target industries through creative and effective outbound strategies. This is a fast-paced, high-impact team that works cross-functionally with Sales, Marketing, Legal, Merchant Risk. This role has a direct impact on high-priority organizational goals, and will provide a pathway to a successful sales career. We are looking for a driven, thoughtful and tenacious individual to join our world-class team and help change consumer finance for the better.&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;qMYqUG_convSearchResultHighlightRoot&quot;&gt;
